import{_ as o,C as r,o as h,c as n,aj as d,E as a}from"./framework.js";const u=JSON.parse('{"title":"控制台：组织 | Product / Console | Documentation","description":"控制台：组织 in Kooboo: 组织页适合先确认“当前正在操作哪个组织”。切换组织后，域名、余额、订单、会员、AI 配置等也会随之变化。","frontmatter":{"title":"控制台：组织 | Product / Console | Documentation","description":"控制台：组织 in Kooboo: 组织页适合先确认“当前正在操作哪个组织”。切换组织后，域名、余额、订单、会员、AI 配置等也会随之变化。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/console/organization.html"}]]},"headers":[],"relativePath":"zh/product/console/organization.md","filePath":"product/console/organization.md","lastUpdated":1780996899000}'),i={name:"zh/product/console/organization.md"};function c(l,t,s,b,p,m){const e=r("DocImage");return h(),n("div",null,[t[0]||(t[0]=d('<h1 id="控制台-组织" tabindex="-1">控制台：组织 <a class="header-anchor" href="#控制台-组织" aria-label="Permalink to &quot;控制台：组织&quot;">​</a></h1><blockquote><p>管理当前账户所在组织、成员、部门，以及组织切换。组织是域名、余额、会员和 AI 配置的归属边界。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>菜单路径</td><td>顶部 <strong>控制台</strong> -&gt; 左侧 <strong>组织</strong></td></tr><tr><td>深链</td><td><code>/_Admin/kconsole/organization</code></td></tr><tr><td>前端路由</td><td><code>/kconsole/organization</code></td></tr><tr><td>可见身份</td><td>所有组织成员可见；成员维护和部门维护需要组织管理员</td></tr></tbody></table><p>组织页适合先确认“当前正在操作哪个组织”。切换组织后，域名、余额、订单、会员、AI 配置等也会随之变化。</p>',5)),a(e,{src:"/product/console/organization-overview.png",alt:"控制台组织成员列表（邮箱与成员名已脱敏）",width:"1120"}),t[1]||(t[1]=d('<h2 id="页面顶部摘要" tabindex="-1">页面顶部摘要 <a class="header-anchor" href="#页面顶部摘要" aria-label="Permalink to &quot;页面顶部摘要&quot;">​</a></h2><p>顶部会显示三项信息：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>当前组织</td><td>当前生效的组织名称</td></tr><tr><td>成员</td><td>当前组织成员数量</td></tr><tr><td>身份</td><td>你在当前组织中是管理员还是普通成员</td></tr></tbody></table><p>右侧两个按钮：</p><table tabindex="0"><thead><tr><th>按钮</th><th>说明</th></tr></thead><tbody><tr><td><code>部门</code></td><td>进入部门管理页</td></tr><tr><td><code>管理组织</code></td><td>打开组织列表，可切换组织、离开组织或创建自己的组织</td></tr></tbody></table><h2 id="成员列表" tabindex="-1">成员列表 <a class="header-anchor" href="#成员列表" aria-label="Permalink to &quot;成员列表&quot;">​</a></h2><p>成员表展示：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>User Name</td><td>用户名；管理员会带 <code>Admin</code> 标识</td></tr><tr><td>Email</td><td>成员邮箱</td></tr><tr><td>Join Date</td><td>加入组织的时间</td></tr></tbody></table><p>如果你是组织管理员，表格上方会显示：</p><table tabindex="0"><thead><tr><th>按钮</th><th>填什么 / 做什么</th></tr></thead><tbody><tr><td><code>添加成员</code></td><td>输入已有用户名，把该用户加入当前组织</td></tr><tr><td><code>创建成员</code></td><td>新建组织用户，填写用户名、密码、邮箱、电话</td></tr><tr><td><code>导出</code></td><td>导出当前组织成员列表</td></tr></tbody></table><p>删除成员时，表格会先弹确认框；管理员成员在列表中不可直接勾选删除。</p><h2 id="添加成员与创建成员" tabindex="-1">添加成员与创建成员 <a class="header-anchor" href="#添加成员与创建成员" aria-label="Permalink to &quot;添加成员与创建成员&quot;">​</a></h2><p>两种入口的区别：</p><table tabindex="0"><thead><tr><th>入口</th><th>适合场景</th><th>表单字段</th></tr></thead><tbody><tr><td>添加成员</td><td>用户已经存在，只是加入当前组织</td><td><code>User Name</code></td></tr><tr><td>创建成员</td><td>需要为组织创建一个新账号</td><td><code>User Name</code>、<code>Password</code>、<code>Email</code>、<code>Phone</code></td></tr></tbody></table><p>创建成员会校验用户名、密码、邮箱与电话格式。成员创建完成后会刷新成员列表。</p><h2 id="管理组织" tabindex="-1">管理组织 <a class="header-anchor" href="#管理组织" aria-label="Permalink to &quot;管理组织&quot;">​</a></h2><p>点击 <code>管理组织</code> 会打开组织列表弹窗。</p><table tabindex="0"><thead><tr><th>区域</th><th>说明</th></tr></thead><tbody><tr><td>组织列表</td><td>显示组织名称、成员数，并标记当前组织</td></tr><tr><td><code>Depart</code></td><td>离开选中的组织；如果你是该组织管理员，该按钮会禁用</td></tr><tr><td><code>Create Own Org</code></td><td>当你没有任何管理员组织时显示</td></tr><tr><td><code>Switch</code></td><td>切换到选中组织</td></tr></tbody></table><p>切换组织或离开组织后，前端会退出当前登录态并返回登录页；重新登录后再继续操作。</p><h2 id="部门" tabindex="-1">部门 <a class="header-anchor" href="#部门" aria-label="Permalink to &quot;部门&quot;">​</a></h2><p>从组织页点击 <code>部门</code> 进入：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/kconsole/departments</span></span></code></pre></div>',22)),a(e,{src:"/product/console/organization-departments.png",alt:"控制台部门列表",width:"1120"}),t[2]||(t[2]=d('<p>部门列表显示：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>Name</td><td>部门名称</td></tr><tr><td>Members</td><td>部门成员数，点击数字可查看部门成员</td></tr></tbody></table><p>组织管理员可点击 <code>Add Department</code> 新建部门，填写 <code>Name</code> 即可。部门成员弹窗中可以：</p><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><code>Add User</code></td><td>从组织成员中选择用户加入部门</td></tr><tr><td>Function</td><td>填写该用户在部门中的职能</td></tr><tr><td>Is Manager</td><td>设置是否为部门负责人</td></tr><tr><td>删除</td><td>从部门中移除选中成员</td></tr></tbody></table><h2 id="常见工作流" tabindex="-1">常见工作流 <a class="header-anchor" href="#常见工作流" aria-label="Permalink to &quot;常见工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>顺序</th></tr></thead><tbody><tr><td>新组织准备上线</td><td>管理组织 -&gt; 确认当前组织 -&gt; 添加成员 / 创建成员 -&gt; 部门</td></tr><tr><td>给实施同学开权限</td><td>创建成员 -&gt; 部门中添加用户 -&gt; 回站点后台配置 <a href="/kb-docs/zh/cms/settings/roles.html">角色权限</a></td></tr><tr><td>切换到客户组织</td><td>管理组织 -&gt; 选择组织 -&gt; Switch -&gt; 重新登录</td></tr><tr><td>离开不再维护的组织</td><td>管理组织 -&gt; 选择组织 -&gt; Depart</td></tr></tbody></table><h2 id="与站点用户的区别" tabindex="-1">与站点用户的区别 <a class="header-anchor" href="#与站点用户的区别" aria-label="Permalink to &quot;与站点用户的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控制台组织成员</th><th>CMS 站点用户</th></tr></thead><tbody><tr><td>决定用户是否属于某个组织，影响控制台域名、余额、会员、AI 配置等账户级能力</td><td>决定用户是否能进入某个站点后台，以及能操作哪些站点功能</td></tr><tr><td>深链 <code>/_Admin/kconsole/organization</code></td><td>深链 <code>/_Admin/system/siteuser?SiteId={GUID}</code></td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./../console.html">控制台概述</a></td><td>控制台菜单地图</td></tr><tr><td><a href="./balance.html">余额</a></td><td>组织级余额</td></tr><tr><td><a href="./ai-config.html">AI 配置</a></td><td>组织级 AI Provider Key</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/site-users.html">CMS：站点用户</a></td><td>站点后台用户</td></tr><tr><td><a href="/kb-docs/zh/cms/settings/roles.html">CMS：角色权限</a></td><td>站点级权限</td></tr></tbody></table>',10))])}const g=o(i,[["render",c]]);export{u as __pageData,g as default};
